    case PM_RUBY_GOLEM: typ = RUBY; break;
    case PM_DIAMOND_GOLEM: typ = DIAMOND; break;
    case PM_SAPPHIRE_GOLEM: typ = SAPPHIRE; break;
    case PM_CRYSTAL_GOLEM: typ = STRANGE_OBJECT; break;
